// Writes the Supabase vars in .env.local from the running local stack (`npm run db:env`).
// Other variables already in .env.local (e.g. GEMINI_API_KEY) are kept.
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, writeFileSync } from "node:fs";

const ENV_FILE = ".env.local";
const MANAGED_KEYS = ["NEXT_PUBLIC_SUPABASE_URL", "NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY", "SUPABASE_SECRET_KEY"];
const MANAGED_COMMENTS = [
  "# Generated by `npm run db:env` from the local Supabase stack. Do not commit.",
  "# Server-only. Bypasses RLS — never expose to the browser.",
];

let status;
try {
  status = JSON.parse(
    execFileSync("supabase", ["status", "-o", "json"], { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] }),
  );
} catch {
  console.error("Local Supabase is not running. Start it with `npm run db:start` first.");
  process.exit(1);
}

const url = status.API_URL;
const publishableKey = status.PUBLISHABLE_KEY ?? status.ANON_KEY;
const secretKey = status.SECRET_KEY ?? status.SERVICE_ROLE_KEY;

if (!url || !publishableKey) {
  console.error("Could not read API_URL / PUBLISHABLE_KEY from `supabase status`.");
  process.exit(1);
}

const supabaseBlock = [
  MANAGED_COMMENTS[0],
  `NEXT_PUBLIC_SUPABASE_URL=${url}`,
  `NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY=${publishableKey}`,
  "",
  MANAGED_COMMENTS[1],
  `SUPABASE_SECRET_KEY=${secretKey ?? ""}`,
];

// Keep every line that this script does not manage (other vars, their comments).
const existing = existsSync(ENV_FILE) ? readFileSync(ENV_FILE, "utf8").split("\n") : [];
const kept = existing.filter((line) => {
  const key = line.split("=")[0].trim();
  return !MANAGED_KEYS.includes(key) && !MANAGED_COMMENTS.includes(line.trim());
});
const rest = kept.join("\n").trim();

writeFileSync(ENV_FILE, [...supabaseBlock, "", ...(rest ? [rest, ""] : [])].join("\n"));
console.log(`Wrote Supabase vars to ${ENV_FILE} (${url})${rest ? ", kept your other variables" : ""}`);
